// Some portions generated by Claude

// The query editor falls back on the deployment's fallback namespaces (namespaces.fallback) for prefixes that the
// repository does not define: typing one adds its PREFIX line, while "Insert prefixes" still adds only the repository's
// namespaces. The bundled list is empty, so these tests serve their own list in place of the server's.
// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	repositoryPageUrl,
	serverBaseUrl,
	uniqueRepositoryId,
	waitForRoute
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-fallback-namespaces');
// Neither seed graph declares skos; the fallback list these tests serve does.
const SKOS = 'PREFIX skos: <http://www.w3.org/2004/02/skos/core#>';
const FALLBACK = {
	skos: 'http://www.w3.org/2004/02/skos/core#',
	foaf: 'http://xmlns.com/foaf/0.1/',
	schema: 'https://schema.org/'
};

test.describe.configure({ mode: 'serial' });

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

/** Opens the Query page once the editor has the fallback namespaces. */
async function openQueryPage(page) {
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.route('**/fallback-namespaces', (route) => route.fulfill({ json: FALLBACK }));
	const fallback = page.waitForResponse((response) => new URL(response.url()).pathname.endsWith('/fallback-namespaces')
		&& response.ok());
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'), { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'query');
	await fallback;
	return page.locator('#query-page .CodeMirror').first();
}

test('typing a prefix the repository does not define adds its PREFIX line from the fallback list', async ({ page }) => {
	const editor = await openQueryPage(page);
	await editor.evaluate((element) => {
		element.CodeMirror.setValue('SELECT * WHERE {\n  ?concept a \n}');
		element.CodeMirror.focus();
		element.CodeMirror.setCursor({ line: 1, ch: 13 });
	});
	await page.keyboard.type('skos:Concept');

	await expect.poll(() => editor.evaluate((element) => element.CodeMirror.getValue())).toContain(SKOS);
	expect(await editor.evaluate((element) => element.CodeMirror.getValue())).toContain('?concept a skos:Concept');
});

test('Insert prefixes adds the repository namespaces and none of the fallback list', async ({ page }) => {
	const editor = await openQueryPage(page);
	await editor.evaluate((element) => element.CodeMirror.setValue('SELECT * WHERE { ?s ?p ?o }'));
	await page.locator('#query-options-toggle').click();
	await page.getByRole('button', { name: 'Insert prefixes' }).click();

	const value = await editor.evaluate((element) => element.CodeMirror.getValue());
	expect(value).toContain('PREFIX bsbm: <http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/vocabulary/>');
	expect(value).not.toContain(SKOS);
	expect(value.split('\n').filter((line) => line.startsWith('PREFIX ')).length,
		'only the repository namespaces, not the fallback ones').toBeLessThan(50);
});
